-- BE-INCR-RETENCOES-FONTE PR-1 (BRIEF itens 1–3 e 5–8; Emenda 22/10; forks F-RET-16, F-RET-17, F-RET-19 ratificados pelo dono em
-- 2026-10-22; executa: dono, chat, 2026-10-24: "executa RETENCOES-FONTE PR-1 e PR-2"). Aditiva: tabela `withholding_profiles`
-- (perfil de retenção por contraparte × natureza), 2 colunas em `counterparties` (regime e declaração de optante, F-RET-5 a) e
-- 7 papéis em `fiscal_profiles` (FK Restrict, nullable = "não configurado", molde F-TA-7). `ALTER TABLE ... ADD COLUMN` em vez
-- do RedefineTables do `prisma migrate diff` (precedente `20261021120000_add_partners_irrf_distribuicao`). Abort no meio deixa
-- as primeiras colunas criadas e o retry morre em "duplicate column": conferir com `PRAGMA table_info`, criar as que faltam e
-- `prisma migrate resolve --applied` (memória migracao-sqlite-nao-e-transacional).
--
-- Dado: tabelas RETENCAO, RETENCAO_CODIGO, NATUREZA_RENDIMENTO e IRRF_PF_MENSAL de parâmetros legais. Os INSERTs são o texto
-- de prisma/data/legal_parameters_retencoes_v1.sql (teste-guarda de igualdade), gerado por
-- pesquisas-legais/retencoes-fonte-pr1-reinf-tabelas/gerar_carga.py do zip oficial "EFD-REINF - Tabelas 15012026.zip"
-- (SHA-256 31c04713…b1a7) e das normas do dossiê. INSERT OR IGNORE com id fixo.

-- CreateTable
CREATE TABLE IF NOT EXISTS "withholding_profiles" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "unitId" TEXT NOT NULL,
    "counterpartyId" TEXT NOT NULL,
    "naturezaServico" TEXT NOT NULL,
    "natRend" TEXT,
    "irrf" BOOLEAN NOT NULL,
    "csrf" BOOLEAN NOT NULL,
    "inss" BOOLEAN NOT NULL,
    "inssTpServico" TEXT,
    "inssCprb" BOOLEAN,
    "issRetido" BOOLEAN NOT NULL,
    "issCodMun" TEXT,
    "issAliquotaBp" INTEGER,
    "issVencimentoDia" INTEGER,
    "fonte" TEXT NOT NULL,
    "vigenteDesde" TEXT NOT NULL,
    "vigenteAte" TEXT,
    "createdById" TEXT,
    "updatedById" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "deletedAt" DATETIME,
    CONSTRAINT "withholding_profiles_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "withholding_profiles_counterpartyId_fkey" FOREIGN KEY ("counterpartyId") REFERENCES "counterparties" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);

-- CreateIndex
CREATE INDEX IF NOT EXISTS "withholding_profiles_userId_unitId_counterpartyId_idx" ON "withholding_profiles"("userId", "unitId", "counterpartyId");

-- AlterTable counterparties
ALTER TABLE "counterparties" ADD COLUMN "regimeTributario" TEXT;
ALTER TABLE "counterparties" ADD COLUMN "declaracaoOptanteDocumentId" TEXT;

-- AlterTable fiscal_profiles
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoIrrfRecolherAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoCsrfRecolherAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoInssRecolherAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoIssRecolherAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoIrrfCompensarAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoCsllCompensarAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "fiscal_profiles" ADD COLUMN "retencaoInssCompensarAccountId" TEXT REFERENCES "accounts" ("id") ON DELETE RESTRICT ON UPDATE CASCADE;

